using System;
using System.Diagnostics;
using System.Runtime.InteropServices;
using TextAnalysis;

// Build input: ~10 000 words
var rng = new Random(42);
var words = new string[10_000];
for (int i = 0; i < words.Length; i++)
{
    int len = rng.Next(1, 15);
    var chars = new char[len];
    for (int j = 0; j < len; j++)
        chars[j] = (char)('a' + rng.Next(0, 26));
    words[i] = new string(chars);
}
var analyzer = new TextAnalyzer(string.Join(' ', words));

Console.WriteLine($"Runtime: {RuntimeInformation.FrameworkDescription}");
Console.WriteLine($"OS: {RuntimeInformation.OSDescription}");
Console.WriteLine();

const int warmup = 500;
const int iterations = 5000;

// --- AverageWordLength ---
for (int i = 0; i < warmup; i++) analyzer.AverageWordLength();
var sw = Stopwatch.StartNew();
for (int i = 0; i < iterations; i++) analyzer.AverageWordLength();
sw.Stop();
Console.WriteLine($"AverageWordLength   : {sw.Elapsed.TotalMicroseconds / iterations,9:F2} µs/op");

// --- WordLengthHistogram ---
for (int i = 0; i < warmup; i++) analyzer.WordLengthHistogram();
sw = Stopwatch.StartNew();
for (int i = 0; i < iterations; i++) analyzer.WordLengthHistogram();
sw.Stop();
Console.WriteLine($"WordLengthHistogram : {sw.Elapsed.TotalMicroseconds / iterations,9:F2} µs/op");

// --- UniqueWordCount ---
for (int i = 0; i < warmup; i++) analyzer.UniqueWordCount();
sw = Stopwatch.StartNew();
for (int i = 0; i < iterations; i++) analyzer.UniqueWordCount();
sw.Stop();
Console.WriteLine($"UniqueWordCount     : {sw.Elapsed.TotalMicroseconds / iterations,9:F2} µs/op");

